html:
{%- set company = frappe.get_doc("Company", doc.company) -%}

<!-- --- DATA MERGING BY CUSTOM ITEM TYPE --- -->
{%- set merged_groups = {} -%}
{%- for item in doc.items -%}
    {%- set item_info = frappe.db.get_value("Item", item.item_code, ["custom_item_type", "stock_uom"], as_dict=1) or {} -%}
    {%- set group_key = item_info.custom_item_type or "Uncategorized" -%}
    {%- set qty = item.ordered_qty | float -%}

    {%- if group_key in merged_groups -%}
        {%- set current_qty = merged_groups[group_key].qty + qty -%}
        {%- set _ = merged_groups[group_key].update({'qty': current_qty}) -%}
        {%- if item.item_code not in merged_groups[group_key].items_included -%}
            {%- set _ = merged_groups[group_key].items_included.append(item.item_code) -%}
        {%- endif -%}
    {%- else -%}
        {%- set new_entry = {
            'type_name': group_key,
            'uom': item_info.stock_uom or "Nos",
            'qty': qty,
            'items_included': [item.item_code]
        } -%}
        {%- set _ = merged_groups.update({group_key: new_entry}) -%}
    {%- endif -%}
{%- endfor -%}
{%- set final_groups_list = merged_groups.values() | list -%}

<!-- --- RELIABLE ADDRESS LOGIC --- -->
{%- set jobber_id = doc.panel_jobber if doc.work_type == "Panel Job Work" else doc.full_piece_jobber -%}
{%- set jobber_name = frappe.db.get_value("Supplier", jobber_id, "supplier_name") or jobber_id -%}
{%- set jobber_address_html = "" -%}

{%- if jobber_id -%}
    {%- set addr_link = frappe.get_all("Dynamic Link", filters={"link_doctype": "Supplier", "link_name": jobber_id, "parenttype": "Address"}, fields=["parent"], limit=1) -%}
    {%- if addr_link -%}
        {%- set addr_doc = frappe.get_doc("Address", addr_link[0].parent) -%}
        {%- set addr_parts = [addr_doc.address_line1, addr_doc.address_line2, addr_doc.city, addr_doc.pincode] -%}
        {%- set clean_parts = [] -%}
        {%- for part in addr_parts -%}{% if part %}{% set _ = clean_parts.append(part) %}{% endif %}{%- endfor -%}
        {%- set jobber_address_html = clean_parts | join(", ") -%}
    {%- endif -%}
{%- endif -%}

<!-- --- PAGINATION --- -->
{% set chunk_size = 20 %} 
{% set total_groups = final_groups_list|length %}
{% set chunks = (total_groups // chunk_size) + (1 if total_groups % chunk_size else 0) %}
{% if chunks == 0 %}{% set chunks = 1 %}{% endif %}

<style>
    @page { margin: 5mm; size: A4; }
    body { font-family: 'Segoe UI', Arial, sans-serif; font-size: 9.5pt; color: #000; margin: 0; }

    .wrapper { 
        border: 2px solid #000; 
        display: flex; 
        flex-direction: column; 
        min-height: 280mm; 
        width: 100%; 
        box-sizing: border-box; 
    }

    table { width: 100%; border-collapse: collapse; }

    /* Header Styles */
    .title-banner { text-align: center; font-weight: bold; font-size: 14pt; border-bottom: 2px solid #000; padding: 6px; background-color: #f4f4f4; }
    .header-table td { border: 1px solid #000; border-top: none; padding: 8px; vertical-align: top; }
    .meta-box { border-bottom: 1px solid #000; display: flex; font-size: 9pt; }
    .meta-box:last-child { border-bottom: none; }
    .meta-label { width: 40%; font-weight: bold; background: #f9f9f9; border-right: 1px solid #000; padding: 3px 5px; }
    .meta-value { width: 60%; padding: 3px 5px; }

    .vendor-section { padding: 12px; border-bottom: 2px solid #000; min-height: 60px; }

    /* Item Table - Lines only where items exist */
    .item-table th { 
        background: #eee; 
        border: 1px solid #000; 
        padding: 8px; 
        text-transform: uppercase; 
        font-size: 8.5pt; 
    }
    .item-table td { 
        border: 1px solid #000; /* Lines are here */
        padding: 8px; 
        vertical-align: top; 
    }

    .text-center { text-align: center; }

    /* Footer Styles */
    .footer { margin-top: auto; border-top: 2px solid #000; }
    .instruction-box { padding: 10px; border-bottom: 1px solid #000; font-size: 8.5pt; }
    .sign-section { display: flex; justify-content: space-between; padding: 25px 15px; text-align: center; }
    .line { border-top: 1px solid #000; width: 80%; margin: 40px auto 5px auto; }
</style>

{% for page_num in range(chunks) %}
<div class="wrapper">
    <div class="title-banner">EMBROIDERY WORK ORDER / CHALLAN</div>

    <table class="header-table">
        <tr>
            <td style="width: 25%; text-align: center; border-left: none;">
                <img src="/files/Dacs inc Logo.jpeg" style="max-height: 65px;">
            </td>
            <td style="width: 40%; text-align: center;">
                <div style="font-size: 11pt; font-weight: bold;">{{ company.name }}</div>
                <div style="font-size: 8pt; margin-top: 4px;">
                    Jaya Sai Towers No.40, Sajjan Rao Road, Bangalore - 560004<br>
                    GSTIN: {{ company.gstin or 'N/A' }}
                </div>
            </td>
            <td style="width: 35%; padding: 0; border-right: none;">
                <div class="meta-box"><div class="meta-label">Order No:</div><div class="meta-value"><strong>{{ doc.name }}</strong></div></div>
                <div class="meta-box"><div class="meta-label">Date:</div><div class="meta-value">{{ frappe.utils.formatdate(doc.date, "dd-MMM-yyyy") }}</div></div>
                <div class="meta-box"><div class="meta-label">Work Type:</div><div class="meta-value">{{ doc.work_type }}</div></div>
            </td>
        </tr>
    </table>

    <div class="vendor-section">
        <span style="font-size: 8pt; font-weight: bold; text-decoration: underline;">ISSUED TO:</span><br>
        <div style="margin-top: 5px;">
            <strong>{{ jobber_name }}</strong><br>
            <span style="font-size: 9pt;">{{ jobber_address_html or 'Address Details Not Found' }}</span>
        </div>
    </div>

    <table class="item-table">
        <thead>
            <tr>
                <th style="width: 5%;">Sr</th>
                <th style="width: 30%;">Item Type</th>
                <th style="width: 45%;">Included Item Codes</th>
                <th style="width: 10%;">Qty</th>
                <th style="width: 10%;">UOM</th>
            </tr>
        </thead>
        <tbody>
            {% set start_idx = page_num * chunk_size %}
            {% set end_idx = start_idx + chunk_size %}
            {% for group in final_groups_list[start_idx:end_idx] %}
            <tr>
                <td class="text-center">{{ loop.index + start_idx }}</td>
                <td style="font-weight: bold;">{{ group.type_name }}</td>
                <td style="font-size: 8.5pt;">{{ group.items_included | join(", ") }}</td>
                <td class="text-center" style="font-weight: bold;">{{ "{:,.2f}".format(group.qty) }}</td>
                <td class="text-center">{{ group.uom }}</td>
            </tr>
            {% endfor %}
            {# No empty rows are generated here, so lines stop exactly after the last item #}
        </tbody>
    </table>

    {% if page_num + 1 == chunks %}
    <div class="footer">
        <div class="instruction-box">
            <strong>Remarks / Instructions:</strong><br>
            {{ doc.instructions or 'Material issued for Embroidery Job Work. Please verify quantity upon receipt.' }}
        </div>

        <div style="display: flex; border-bottom: 1px solid #000; background: #fafafa;">
             <div style=" padding: 8px; text-align: left; font-weight: bold;">GRAND TOTAL QUANTITY:</div>
             <div style="padding: 8px; text-align: center; font-weight: bold; font-size: 11pt;">
                {% set grand_total = namespace(v=0) %}
                {% for g in final_groups_list %}{% set grand_total.v = grand_total.v + g.qty %}{% endfor %}
                {{ "{:,.2f}".format(grand_total.v) }}
             </div>
        </div>

        <div class="sign-section">
            <div style="width: 30%;">
                <div class="line"></div>
                Receiver's Signature
            </div>
            <div style="width: 30%;">
                <div class="line"></div>
                Verified By
            </div>
            <div style="width: 30%;">
                <div style="font-size: 8.5pt;">For <strong>{{ company.name }}</strong></div>
                <div class="line"></div>
                Authorised Signatory
            </div>
        </div>
    </div>
    {% else %}
    <div style="padding: 10px; text-align: right; font-style: italic;">Continued on next page...</div>
    {% endif %}
</div>
{% if not loop.last %}<div class="page-break"></div>{% endif %}
{% endfor %}
